SELECT *, AVG(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS rating_avg_5, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating, id) AS seq_no, AVG(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS rating_avg_2_prior, PERCENT_RANK() OVER (PARTITION BY country ORDER BY rating DESC NULLS LAST) AS rating_percent_rank FROM suppliers
